import{_ as l,o as i,c as e,ak as n}from"./chunks/framework.DvrM7GBU.js";const o=JSON.parse('{"title":"创游地图与对象结构猜想","description":"","frontmatter":{},"headers":[],"relativePath":"社区分析/专题研究/创游地图与对象结构猜想.md","filePath":"社区分析/专题研究/创游地图与对象结构猜想.md","lastUpdated":1776864657000}'),s={name:"社区分析/专题研究/创游地图与对象结构猜想.md"};function r(p,a,h,t,c,d){return i(),e("div",null,[...a[0]||(a[0]=[n(`<h1 id="创游地图与对象结构猜想" tabindex="-1">创游地图与对象结构猜想 <a class="header-anchor" href="#创游地图与对象结构猜想" aria-label="Permalink to “创游地图与对象结构猜想”">​</a></h1><p>本文件根据 <code>资料/其他用户给的解析.txt</code> 中关于地图层级、图层、地块、镜头、对象组织方式的内容拆分整理，作为社区结构观察专题。</p><blockquote><p>说明：内容为社区研究线索，不代表官方正式实现说明。</p></blockquote><h2 id="_1-已给出的结构示意" tabindex="-1">1. 已给出的结构示意 <a class="header-anchor" href="#_1-已给出的结构示意" aria-label="Permalink to “1. 已给出的结构示意”">​</a></h2><p>原文给出地图结构示意：</p><div class="language-text line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>当前地图</span></span>
<span class="line"><span>┗背景</span></span>
<span class="line"><span>┗自定义层级</span></span>
<span class="line"><span>    ┗图层1</span></span>
<span class="line"><span>        ┗未命名</span></span>
<span class="line"><span>            ┗（用来管理地块的）</span></span>
<span class="line"><span>        ┗（这是物体）</span></span>
<span class="line"><span>        ┗（这是物体）</span></span>
<span class="line"><span>         ……</span></span>
<span class="line"><span>    ┗（其他层级）</span></span>
<span class="line"><span>┗镜头</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br></div></div><h2 id="_2-从这个示意能看出什么" tabindex="-1">2. 从这个示意能看出什么 <a class="header-anchor" href="#_2-从这个示意能看出什么" aria-label="Permalink to “2. 从这个示意能看出什么”">​</a></h2><p>至少能看出地图不是“一个平面画布”，而是存在明显层次：</p><ul><li>顶层有当前地图</li><li>地图下有背景</li><li>有自定义层级</li><li>层级下有图层</li><li>图层下又可能包含地块管理节点与普通物体节点</li><li>还有镜头对象</li></ul><p>这和许多游戏编辑器里的“场景树/节点树”概念高度相似。</p><h2 id="_3-地块与普通物体可能不是同一类节点" tabindex="-1">3. 地块与普通物体可能不是同一类节点 <a class="header-anchor" href="#_3-地块与普通物体可能不是同一类节点" aria-label="Permalink to “3. 地块与普通物体可能不是同一类节点”">​</a></h2><p>原文专门把某个“未命名”节点标为：</p><ul><li>用来管理地块的</li></ul><p>同时另外一些节点则被描述为：</p><ul><li>这是物体</li></ul><h3 id="这意味着" tabindex="-1">这意味着 <a class="header-anchor" href="#这意味着" aria-label="Permalink to “这意味着”">​</a></h3><p>地块虽然也属于地图内容，但在结构上可能是“集中管理”的，而不是完全与普通物体等价。</p><h3 id="对理解编辑器很重要" tabindex="-1">对理解编辑器很重要 <a class="header-anchor" href="#对理解编辑器很重要" aria-label="Permalink to “对理解编辑器很重要”">​</a></h3><p>这可以解释为什么：</p><ul><li>地块系统常常有专用编辑方式</li><li>地块有特殊属性，如阻挡、摩擦、可摧毁</li><li>地块可能在渲染、碰撞和编辑逻辑上和普通物体不同</li></ul><h2 id="_4-镜头被视为独立节点的意义" tabindex="-1">4. 镜头被视为独立节点的意义 <a class="header-anchor" href="#_4-镜头被视为独立节点的意义" aria-label="Permalink to “4. 镜头被视为独立节点的意义”">​</a></h2><p>原文结构里单独列出：</p><ul><li>镜头</li></ul><h3 id="这说明" tabindex="-1">这说明 <a class="header-anchor" href="#这说明" aria-label="Permalink to “这说明”">​</a></h3><p>镜头很可能不是某个普通物体属性，而是地图结构中的一个独立控制对象。</p><h3 id="对脚本层的启发" tabindex="-1">对脚本层的启发 <a class="header-anchor" href="#对脚本层的启发" aria-label="Permalink to “对脚本层的启发”">​</a></h3><p>如果镜头是独立节点，那么很多镜头脚本可能意味着：</p><ul><li>不是改物体属性</li><li>而是在操作地图级视觉控制对象</li></ul><p>这与后续版本更新里修复“镜头跟踪速度受地图运行速度影响”等问题也可以互相印证。</p><h2 id="_5-当前地图-和-地图物体-耦合的猜测" tabindex="-1">5. “当前地图”和“地图物体”耦合的猜测 <a class="header-anchor" href="#_5-当前地图-和-地图物体-耦合的猜测" aria-label="Permalink to “5. “当前地图”和“地图物体”耦合的猜测”">​</a></h2><p>原文还提到一个很关键的观察：</p><ul><li>地图物体本身和当前地图居然是共用一个对象</li></ul><h3 id="如果这个观察成立-意味着什么" tabindex="-1">如果这个观察成立，意味着什么 <a class="header-anchor" href="#如果这个观察成立-意味着什么" aria-label="Permalink to “如果这个观察成立，意味着什么”">​</a></h3><ul><li>地图级 API 和某些物体级 API 的底层封装可能耦合很深</li><li>“地图”未必是一个完全独立的数据抽象层</li><li>有些脚本里看似不同的访问入口，底层可能指向相近对象模型</li></ul><h3 id="为什么这会带来问题" tabindex="-1">为什么这会带来问题 <a class="header-anchor" href="#为什么这会带来问题" aria-label="Permalink to “为什么这会带来问题”">​</a></h3><p>一旦抽象边界不清晰，就容易出现：</p><ul><li>某些行为只在特定上下文下成立</li><li>某些参数传入后静默失败</li><li>某些对象接口看似通用，实则只适用于部分场景</li></ul><h2 id="_6-与节点树功能的互证" tabindex="-1">6. 与节点树功能的互证 <a class="header-anchor" href="#_6-与节点树功能的互证" aria-label="Permalink to “6. 与节点树功能的互证”">​</a></h2><p>结合引擎更新中的“支持以节点树形式查看子物体并支持调整顺序和父子关系”，可以发现社区观察与官方更新之间存在可互证点：</p><ul><li>地图/物体系统确实很可能建立在树状结构上</li><li>子物体不是简单标签，而是有明确父子关系</li><li>顺序与层级可能直接影响表现或逻辑</li></ul><p>这说明地图结构研究不只是纯猜想，而是确实能从后续功能里看到一些旁证。</p><h2 id="_7-可继续验证的问题" tabindex="-1">7. 可继续验证的问题 <a class="header-anchor" href="#_7-可继续验证的问题" aria-label="Permalink to “7. 可继续验证的问题”">​</a></h2><p>未来可以围绕这些问题继续做实验：</p><ul><li>地块节点和普通物体节点在属性面板中有什么差异？</li><li>镜头对象能否像普通物体一样被脚本广泛访问？</li><li>地图广播的接收者层级是什么？</li><li>地图属性、系统属性、物体属性之间的同步边界在哪里？</li><li>子物体生成后在节点树里处于什么位置？</li></ul><h2 id="_8-对知识库的意义" tabindex="-1">8. 对知识库的意义 <a class="header-anchor" href="#_8-对知识库的意义" aria-label="Permalink to “8. 对知识库的意义”">​</a></h2><p>这个专题适合回答一类“结构性问题”：</p><ul><li>创游的地图内部是怎么分层的？</li><li>地块为什么像特殊节点？</li><li>镜头为什么单独存在？</li><li>当前地图和地图物体到底是什么关系？</li><li>节点树功能说明了什么？</li></ul><h2 id="_9-关键词" tabindex="-1">9. 关键词 <a class="header-anchor" href="#_9-关键词" aria-label="Permalink to “9. 关键词”">​</a></h2><ul><li>当前地图</li><li>背景</li><li>自定义层级</li><li>图层</li><li>地块管理</li><li>普通物体</li><li>镜头</li><li>节点树</li><li>父子关系</li><li>地图结构</li><li>对象结构</li></ul>`,49)])])}const u=l(s,[["render",r]]);export{o as __pageData,u as default};
